import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])
board = data[1:]

crosses = 0
for i in range(n):
    for j in range(n):
        if board[i][j] == '#':
            if i > 0 and i < n - 1 and j > 0 and j < n - 1:
                if board[i-1][j] == '#' and board[i+1][j] == '#' and board[i][j-1] == '#' and board[i][j+1] == '#':
                    crosses += 1

if crosses * 5 == sum(row.count('#') for row in board):
    print("YES")
else:
    print("NO")

